@theme {
  --font-display: "Cormorant Garamond", "Times New Roman", Georgia, serif;
  --font-sans: "DM Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
}

@layer base {
  html {
    background-color: #000000;
    color: #ffffff;
    font-family: var(--font-sans);
    scroll-behavior: smooth;
  }

  @media (prefers-reduced-motion: reduce) {
    html {
      scroll-behavior: auto;
    }
    *,
    *::before,
    *::after {
      scroll-behavior: auto !important;
    }
    .morta-unfurl-line,
    .morta-rise-headline,
    .morta-fade-copy,
    .morta-fade-cta {
      animation: none !important;
    }
    .group:hover img {
      transform: none !important;
    }
  }
}

@keyframes mortaLineUnfurl {
  0% {
    transform: scaleX(0);
    opacity: 0;
  }
  100% {
    transform: scaleX(1);
    opacity: 1;
  }
}

@keyframes mortaRiseMask {
  0% {
    transform: translateY(100%);
    opacity: 0;
  }
  100% {
    transform: translateY(0%);
    opacity: 1;
  }
}

@keyframes mortaFadeLock {
  0% {
    transform: translateY(12px);
    opacity: 0;
  }
  100% {
    transform: translateY(0);
    opacity: 1;
  }
}

.morta-unfurl-line {
  transform-origin: left center;
  animation: mortaLineUnfurl 0.9s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.morta-rise-headline {
  animation: mortaRiseMask 0.95s cubic-bezier(0.16, 1, 0.3, 1) 0.15s both;
}

.morta-fade-copy {
  animation: mortaFadeLock 0.85s cubic-bezier(0.16, 1, 0.3, 1) 0.32s both;
}

.morta-fade-cta {
  animation: mortaFadeLock 0.85s cubic-bezier(0.16, 1, 0.3, 1) 0.45s both;
}

/* Quiet, mineral surfaces give the silver room to emerge from shadow. */
.morta-atmosphere {
  background: radial-gradient(ellipse at 15% 20%, #202020 0%, #111111 43%, #0b0b0b 100%);
}

.morta-slate {
  background-color: #151515;
  background-image:
    radial-gradient(ellipse at 82% 16%, rgba(110, 112, 110, 0.11), transparent 46%),
    radial-gradient(ellipse at 12% 78%, rgba(75, 78, 77, 0.14), transparent 48%),
    linear-gradient(125deg, #111212, #1b1c1c 48%, #101111);
}

.morta-ring-light {
  background: radial-gradient(ellipse at 50% 43%, #393b3a 0%, #202221 32%, #0c0d0d 75%);
}

/* Architectural artwork adapted from the approved MORTA background study. */
.morta-house-bg,
.morta-collection-bg,
.morta-craft-bg,
.morta-commissions-bg {
  background-color: #070708;
  background-repeat: no-repeat;
  background-position: center top;
  background-size: cover;
}

.morta-house-bg { background-image: url('./architecture/house.svg'); }
.morta-collection-bg { background-image: url('./architecture/collection.svg'); }
.morta-craft-bg {
  background-image: url('./architecture/craft.svg');
  background-size: 100% auto;
}
.morta-commissions-bg { background-image: url('./architecture/commissions.svg'); }

.morta-hero-architecture {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: url('./architecture/hero.svg') center / cover no-repeat;
  mix-blend-mode: screen;
  opacity: 0.4;
}

@media (max-width: 767px) {
  .morta-house-bg { background-size: auto 800px; background-position: 55% top; }
  .morta-craft-bg { background-size: auto 950px; background-position: 35% top; }
  .morta-commissions-bg { background-size: auto 950px; background-position: 32% top; }
  .morta-hero-architecture { background-position: 60% center; opacity: 0.3; }
}

/* A final architectural vista, with a dark veil for the footer navigation. */
.morta-footer {
  position: relative;
  background: #08090a url('/templates/morta/morta-footer-cathedral.webp') center 48% / cover no-repeat;
}

.morta-footer::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0.18), rgba(0, 0, 0, 0.8) 55%, rgba(0, 0, 0, 0.93));
  pointer-events: none;
}

@media (max-width: 767px) {
  .morta-footer { background-position: center top; }
  .morta-footer::before {
    background: linear-gradient(to bottom, rgba(0, 0, 0, 0.3), rgba(0, 0, 0, 0.85) 38%, rgba(0, 0, 0, 0.94));
  }
}

